Conteo contar_lineas(const std::string& bytes) {
    Conteo resultado;
    std::string linea;
    bool hay_bytes = false;
    const auto terminar = [&]() -> bool {
        ++resultado.lineas;
        if (resultado.lineas > 100) {
            resultado = Conteo{0, 0, 0, true};
            return false;
        }
        if (linea.empty()) ++resultado.vacias;
        if (linea.find('\r') != std::string::npos)
            ++resultado.cr_sueltos;
        linea.clear();
        hay_bytes = false;
        return true;
    };
    for (char c : bytes) {
        if (c == '\n') {
            if (!linea.empty() && linea.back() == '\r')
                linea.pop_back();
            if (!terminar()) return resultado;
        } else {
            linea.push_back(c);
            hay_bytes = true;
        }
    }
    if (hay_bytes) terminar();
    return resultado;
}

